def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 100:
        return 'C'

    my_score = 0
    opp_score = 0
    for i, (a, b) in enumerate(history):
        if a == 'C' and b == 'C':
            my_score += 3
            opp_score += 3
        elif a == 'C' and b == 'D':
            my_score += 0
            opp_score += 5
        elif a == 'D' and b == 'C':
            my_score += 5
            opp_score += 0
        else:
            my_score += 1
            opp_score += 1

    opp_c = sum(1 for _, b in history if b == 'C')
    my_c = sum(1 for a, _ in history if a == 'C')

    def opp_coop_rate(start=0):
        cnt = 0
        tot = 0
        for i in range(start, n):
            tot += 1
            if history[i][1] == 'C':
                cnt += 1
        if tot == 0:
            return 0.5
        return cnt / tot

    recent_len = min(10, n)
    recent_opp = opp_coop_rate(n - recent_len)
    overall_opp = opp_coop_rate(0)

    last_me, last_opp = history[-1]

    if n == 1:
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n >= 2:
        l2m, l2o = history[-2]
    else:
        l2m, l2o = last_me, last_opp

    defection_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'D':
            defection_streak += 1
        else:
            break

    cooperation_streak = 0
    for i in range(n - 1, -1, -1):
        if history[i][1] == 'C':
            cooperation_streak += 1
        else:
            break

    score_diff = my_score - opp_score

    rounds_left = 100 - n

    if recent_opp <= 0.15 and defection_streak >= 2:
        return 'D'

    if rounds_left <= 2:
        if last_opp == 'C' and recent_opp > 0.4:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if rounds_left <= 6:
        if recent_opp >= 0.7:
            return 'C'
        if recent_opp <= 0.3:
            return 'D'
        if last_opp == 'D':
            return 'D'
        return 'C'

    if n >= 3:
        if history[-1][1] == 'D' and history[-2][1] == 'D' and history[-3][1] == 'D':
            if rng.random() < 0.9:
                return 'D'
            return 'C'

    if last_opp == 'C' and recent_opp >= 0.6:
        return 'C'

    if overall_opp >= 0.75 and recent_opp >= 0.5:
        return 'C'

    if last_opp == 'D':
        if recent_opp >= 0.55:
            return 'C'
        if defection_streak >= 3:
            if rng.random() < 0.85:
                return 'D'
            return 'C'
        if defection_streak >= 2:
            if rng.random() < 0.7:
                return 'D'
            return 'C'
        if rng.random() < 0.55:
            return 'D'
        return 'C'

    if recent_opp >= 0.5:
        return 'C'

    if recent_opp < 0.35:
        if score_diff < -5:
            return 'D'
        if rng.random() < 0.35:
            return 'D'
        return 'C'

    return 'C'
